Note that  $\ds{\quad\ic \equiv \root{-1}}$  !!!. 

 \begin{align}
\int_{0}^{\pi}\cot\pars{t - \ic}\,\dd t & =
\int_{-\ic}^{\pi - \ic}\cot\pars{t}\,\dd t =
\int_{-\ic/\pi}^{1 - \ic/\pi}\pi\cot\pars{\pi t}\,\dd t
\\[5mm] & =
\int_{-\ic/\pi}^{1 - \ic/\pi}
\bracks{\Psi\pars{1 - t} - \Psi\pars{t}}\dd t
\\[5mm] & =
\int_{-\ic/\pi}^{1 - \ic/\pi}
