\totald{}{t}\ln\pars{\vphantom{A^{A^{A}}}
\Gamma\pars{1 - t}\Gamma\pars{t}}\,\dd t
\\[5mm] & =
-\int_{-\ic/\pi}^{1 - \ic/\pi}
\totald{}{t}\ln\pars{\pi \over \sin\pars{\pi t}}\,\dd t
\\[5mm] & =
